def is_tuple_visible(xmin: int, xmax: int, snap_xmin: int, snap_xmax: int, is_frozen: bool) -> bool:
    if is_frozen:
        return xmax == 0 or xmax >= snap_xmax
    if xmin >= snap_xmax:
        return False
    return xmax == 0 or xmax >= snap_xmax

def should_trigger_anti_wraparound(relfrozenxid_age: int, freeze_max_age: int = 200_000_000) -> str:
    if relfrozenxid_age < 0:
        raise ValueError('XID age must be non-negative')
    if relfrozenxid_age >= 1_997_000_000:
        return 'EMERGENCY_READ_ONLY_STOP'
    if relfrozenxid_age >= freeze_max_age:
        return 'AGGRESSIVE_ANTI_WRAPAROUND_VACUUM'
    return 'NORMAL_AUTOVACUUM'

def compute_global_xmin_horizon(backend_xmins: list[int], slot_xmins: list[int], current_xid: int) -> int:
    candidates = [x for x in (backend_xmins + slot_xmins) if x > 0]
    return min(candidates) if candidates else current_xid

def can_use_hot_update(indexed_col_changed: bool, page_free_bytes: int, new_tuple_bytes: int) -> bool:
    if indexed_col_changed:
        return False
    return page_free_bytes >= new_tuple_bytes

def vacuum_mb_per_sec(cost_limit: int, cost_delay_ms: float, cost_page_miss: int = 2) -> float:
    if cost_delay_ms <= 0 or cost_page_miss <= 0:
        raise ValueError('cost_delay_ms and cost_page_miss must be positive')
    cycles_per_sec = 1000.0 / cost_delay_ms
    pages_per_sec = (cost_limit / cost_page_miss) * cycles_per_sec
    return round((pages_per_sec * 8192) / (1024 * 1024), 2)

def evaluate_xid_alert(max_xid_age: int) -> str:
    if max_xid_age >= 1_500_000_000:
        return 'PAGE_SEV1_IMMEDIATE_VACUUM_FREEZE'
    if max_xid_age >= 500_000_000:
        return 'WARN_CHECK_BLOCKING_XMIN_AND_SLOTS'
    if max_xid_age >= 150_000_000:
        return 'INFO_MONITOR_AUTOVACUUM_PROGRESS'
    return 'OK'
